import{_ as a,o as i,c as t,a3 as o}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"Factory Preview Information","description":"","frontmatter":{"translationSource":{"title":"前瞻基建相关信息","archivedAt":"2026-11-23","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=fsJYZfKeanEF8by8G17JcB","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/1-7-factory-preview-information"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/1-7-factory-preview-information"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/1-7-factory-preview-information"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/1-7-factory-preview-information"}]]},"headers":[],"relativePath":"1-7-factory-preview-information.md","filePath":"logistics/src/page-fsJYZfKeanEF8by8G17JcB.md"}'),r={name:"1-7-factory-preview-information.md"};function s(n,e,c,d,p,l){return i(),t("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="factory-preview-information" tabindex="-1">Factory Preview Information <a class="header-anchor" href="#factory-preview-information" aria-label="Permalink to &quot;Factory Preview Information&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-23T06-44-45-722Z-4358a738" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-23. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-23T06:44:47.018Z">2026-11-23</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID:<code>fsJYZfKeanEF8by8G17JcB</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=fsJYZfKeanEF8by8G17JcB" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p><img src="/endfield-skydoc/logistics/src/assets/images/img-8d6f57dd8dbf001d.q90-8467606bc6e699dc.webp" alt="Factory Preview Information"></p><p>Submission items a, b, and c</p><blockquote><p>Translation note. The material labels inside the recipe estimates describe properties and ingredients.</p></blockquote><p>CuPKG Luminarite Components + CuPKG Heavy IC + Lucidolite Energy Bricks</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-a5019e76007be08e.q90-7a4ff20d69b60508.webp" alt="Factory Preview Information"></p><p>15 (?) parts from Turbid Cuprium + 2 Heavy Xiranite = 1 submission item b (Packaging Unit, 10 s)</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-9ff39b86862ea120.q90-3b5f092a0da125fc.webp" alt="Factory Preview Information"></p><p>10 parts from Luminous Cuprium + 5 Luminous Xiranite = 1 submission item a (Packaging Unit, 10 s; considered likely)</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-b3f0a85b16bcf80d.q90-8c501d5d38b68bd0.webp" alt="Factory Preview Information"></p><p>10 parts from equilibrium-treated Cuprium + 10 Dense Originium Powder = 1 submission item C (Packaging Unit, 10 s)</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-36c58912ef222ece.q90-3bf147eff80d2d42.webp" alt="Factory Preview Information"></p><p>The area measures 65×65 (possibly before the final upgrade).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-7e621d3c2b1c1cf8.q90-3379968e973aa409.webp" alt="Factory Preview Information"></p><p>Overlap among 4 zones gives a 100% chance of transformation. A Forge of Luminance creates 1 zone and a Bipolar Forge of Luminance creates 2 zones at right angles (90°). Activation takes 6 Xiragen.</p><p>Tentative: The number of Forges of Luminance seems limited, with at least 14 available.<br> Possible Forge of Equilibrium recipe: Luminous Xiranite + Turbid Xiranite = Heavy Xiranite (considered likely, exact yield uncertain). The note estimates 2 per 10 s.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c946f975f91dcb7a.q90-d71482d688f4fcec.webp" alt="Factory Preview Information"></p><p>The fifth day has a furnace-capacity expansion. My guess is 5 more (possibly 4, 6, or 8).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-82ff1383b12894d5.q90-98338ab8dc38250c.webp" alt="Factory Preview Information"></p><p>Tentative sequence: Forge of Luminance, Rebuilding Supply Port, unlock the T-Array, Forge of Equilibrium, unlock the E-Array, Bipolar Forge of Luminance.</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-c32612bd6f4cf7ec.q90-565cde4c45a5e30e.webp" alt="Factory Preview Information"></p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-311cfcd3df6e549c.q90-f287730f08322728.webp" alt="Factory Preview Information"></p><p>Coverage of the regular Forge of Luminance (in case anyone needs it).</p><p><img src="/endfield-skydoc/logistics/src/assets/images/img-96e72320c00ef57d.q90-78aba4a652b8817c.webp" alt="Factory Preview Information"></p><p>Coverage of the Bipolar Forge of Luminance: Xiragen enters at the top, and zones form on the right and below.</p><p><span id="source-block-3MpyPySCSGgJWLdaFgCXB5"></span></p><h2 id="new-facilities-products-and-recipes" tabindex="-1">New Facilities, Products and Recipes: <a class="header-anchor" href="#new-facilities-products-and-recipes" aria-label="Permalink to &quot;New Facilities, Products and Recipes:&quot;">​</a></h2><p><span id="source-block-nKwi1jcOMD9o6nQxDVm9JJ"></span></p><h2 id="leaked-production-line-screenshots" tabindex="-1">Leaked Production-Line Screenshots: <a class="header-anchor" href="#leaked-production-line-screenshots" aria-label="Permalink to &quot;Leaked Production-Line Screenshots:&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th></tr></thead><tbody><tr><td></td></tr></tbody></table><blockquote><p>Data table (1 record): the public visitor session could not read the record contents. Log in to Tencent Docs to view them.</p></blockquote><p><span id="source-block-wNkadqrBiCvuYL7brm0iva"></span></p><h2 id="leaked-production-line-layout-blueprints" tabindex="-1">Leaked Production-Line Layout Blueprints: <a class="header-anchor" href="#leaked-production-line-layout-blueprints" aria-label="Permalink to &quot;Leaked Production-Line Layout Blueprints:&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th></tr></thead><tbody><tr><td></td></tr></tbody></table><blockquote><p>Data table (1 record): the public visitor session could not read the record contents. Log in to Tencent Docs to view them.</p></blockquote><p><span id="source-block-B2I8uzZu7IKpVVVtbYM1g7"></span></p><h2 id="recipe-speculation" tabindex="-1">Recipe Speculation: <a class="header-anchor" href="#recipe-speculation" aria-label="Permalink to &quot;Recipe Speculation:&quot;">​</a></h2><p><span id="source-block-XiwVHHvXAMpB7pxXnx2anJ"></span></p><h2 id="recipe-analysis" tabindex="-1">Recipe Analysis: <a class="header-anchor" href="#recipe-analysis" aria-label="Permalink to &quot;Recipe Analysis:&quot;">​</a></h2></div>',1)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
